const labelMap = {
  topic: '专题评估',
  comprehensive: '综合评估',
  party_self: '党性自评',
  party_review: '党性复评'
};
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: labelMap[r.kind] || r.kind, value: Math.round((Number(r.avgScore) || 0) * 10) / 10 };
});
return {
  tooltip: { trigger: 'axis' },
  grid: { left: 40, right: 20, bottom: 60, top: 30 },
  xAxis: { type: 'category', data: data.map(function (d) { return d.name; }), axisLabel: { interval: 0 } },
  yAxis: { type: 'value', minInterval: 1 },
  series: [{ type: 'bar', name: '评估类型平均分', data: data.map(function (d) { return d.value; }), barMaxWidth: 40, label: { show: true, position: 'top' } }]
};
